/**
 * Schema-drift tooling.
 *
 * The CMS schema is the source of truth and it changes over time. The OpenAPI
 * spec may lag behind code, so instead we read the generated `payload-types.ts`
 * (regenerated by `pnpm generate:types` in the CMS repo) and extract the field
 * list per collection. `sync-schema` stores a snapshot; `cms_schema_doctor`
 * re-parses the current file and reports added/removed fields so the operator
 * knows when (and where) the MCP helpers may need refreshing.
 */
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { basename, dirname, resolve } from "node:path";

const __dirname = dirname(fileURLToPath(import.meta.url));
// Resolve to the project root. Module lives in src/ (tsx) or dist/ (node),
// both one level under the project root — so "../" lands at the root either way.
export const SNAPSHOT_PATH = resolve(__dirname, "..", "schema.snapshot.json");

export interface SchemaSnapshot {
  generatedAt: string;
  source: string;
  collections: Record<string, string[]>;
}

/** Extract slug -> field-name[] from payload-types.ts source. */
export function extractSchemaFromSource(src: string): Record<string, string[]> {
  const result: Record<string, string[]> = {};

  // 1) slug -> InterfaceName from `export interface Config { collections: { ... } }`
  const slugToType = extractCollectionMap(src);

  // 2) field names for each interface
  for (const [slug, typeName] of Object.entries(slugToType)) {
    const fields = extractInterfaceFields(src, typeName);
    if (fields) result[slug] = fields;
  }
  return result;
}

function extractCollectionMap(src: string): Record<string, string> {
  const map: Record<string, string> = {};
  const idx = src.indexOf("collections:");
  if (idx === -1) return map;
  // Take the object block right after `collections:`
  const braceStart = src.indexOf("{", idx);
  if (braceStart === -1) return map;
  let depth = 0;
  let end = braceStart;
  for (let i = braceStart; i < src.length; i++) {
    if (src[i] === "{") depth++;
    else if (src[i] === "}") {
      depth--;
      if (depth === 0) {
        end = i;
        break;
      }
    }
  }
  const block = src.slice(braceStart + 1, end);
  const re = /['"]?([A-Za-z0-9_-]+)['"]?\s*:\s*([A-Za-z0-9_]+)\s*;/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(block))) {
    map[m[1]] = m[2];
  }
  return map;
}

function extractInterfaceFields(src: string, typeName: string): string[] | null {
  const re = new RegExp(`export interface ${typeName}\\s*\\{`);
  const m = re.exec(src);
  if (!m) return null;
  const braceStart = src.indexOf("{", m.index);
  let depth = 0;
  let end = braceStart;
  for (let i = braceStart; i < src.length; i++) {
    if (src[i] === "{") depth++;
    else if (src[i] === "}") {
      depth--;
      if (depth === 0) {
        end = i;
        break;
      }
    }
  }
  const body = src.slice(braceStart + 1, end);

  // Only capture top-level fields (brace depth 0 within the interface body).
  const fields: string[] = [];
  let d = 0;
  for (const rawLine of body.split("\n")) {
    const line = rawLine.trim();
    if (d === 0) {
      const fm = /^['"]?([A-Za-z0-9_]+)['"]?\??\s*:/.exec(line);
      if (fm) fields.push(fm[1]);
    }
    // Track depth using braces/brackets on the line.
    for (const ch of line) {
      if (ch === "{" || ch === "[") d++;
      else if (ch === "}" || ch === "]") d--;
    }
    if (d < 0) d = 0;
  }
  return fields;
}

export function parseTypesFile(path: string): Record<string, string[]> {
  const src = readFileSync(path, "utf8");
  return extractSchemaFromSource(src);
}

/**
 * Source path as stored in the snapshot: from the CMS repo folder on (the folder that holds
 * `src/`), with forward slashes, so the file never carries the author's local path.
 *   C:/work/my-cms/src/payload-types.ts -> my-cms/src/payload-types.ts
 */
export function portableSource(typesPath: string): string {
  const norm = typesPath.replace(/\\/g, "/");
  const i = norm.lastIndexOf("/src/");
  if (i <= 0) return basename(norm);
  return norm.slice(norm.lastIndexOf("/", i - 1) + 1);
}

export function writeSnapshot(typesPath: string): SchemaSnapshot {
  const collections = parseTypesFile(typesPath);
  const snapshot: SchemaSnapshot = {
    generatedAt: new Date().toISOString(),
    source: portableSource(typesPath),
    collections,
  };
  writeFileSync(SNAPSHOT_PATH, JSON.stringify(snapshot, null, 2) + "\n", "utf8");
  return snapshot;
}

export function loadSnapshot(): SchemaSnapshot | null {
  if (!existsSync(SNAPSHOT_PATH)) return null;
  try {
    return JSON.parse(readFileSync(SNAPSHOT_PATH, "utf8")) as SchemaSnapshot;
  } catch {
    return null;
  }
}

export interface DriftReport {
  hasSnapshot: boolean;
  typesPath: string | null;
  changedCollections: Array<{
    collection: string;
    added: string[];
    removed: string[];
  }>;
  addedCollections: string[];
  removedCollections: string[];
  upToDate: boolean;
  note: string;
}

/** Compare the stored snapshot against the current payload-types.ts. */
export function doctor(typesPath: string | undefined): DriftReport {
  const snapshot = loadSnapshot();
  if (!typesPath) {
    return {
      hasSnapshot: !!snapshot,
      typesPath: null,
      changedCollections: [],
      addedCollections: [],
      removedCollections: [],
      upToDate: false,
      note: "CMS_PAYLOAD_TYPES_PATH is not set; cannot compare against current code. Set it to the path of payload-types.ts in the CMS repo.",
    };
  }
  if (!existsSync(typesPath)) {
    return {
      hasSnapshot: !!snapshot,
      typesPath,
      changedCollections: [],
      addedCollections: [],
      removedCollections: [],
      upToDate: false,
      note: `payload-types.ts not found at ${typesPath}.`,
    };
  }

  const current = parseTypesFile(typesPath);

  if (!snapshot) {
    return {
      hasSnapshot: false,
      typesPath,
      changedCollections: [],
      addedCollections: Object.keys(current),
      removedCollections: [],
      upToDate: false,
      note: "No snapshot yet. Run `npm run sync-schema` to create the baseline.",
    };
  }

  const changed: DriftReport["changedCollections"] = [];
  const allSlugs = new Set([...Object.keys(snapshot.collections), ...Object.keys(current)]);
  const addedCollections: string[] = [];
  const removedCollections: string[] = [];

  for (const slug of allSlugs) {
    const oldF = snapshot.collections[slug];
    const newF = current[slug];
    if (!oldF) {
      addedCollections.push(slug);
      continue;
    }
    if (!newF) {
      removedCollections.push(slug);
      continue;
    }
    const oldSet = new Set(oldF);
    const newSet = new Set(newF);
    const added = newF.filter((f) => !oldSet.has(f));
    const removed = oldF.filter((f) => !newSet.has(f));
    if (added.length || removed.length) changed.push({ collection: slug, added, removed });
  }

  const upToDate = !changed.length && !addedCollections.length && !removedCollections.length;
  return {
    hasSnapshot: true,
    typesPath,
    changedCollections: changed,
    addedCollections,
    removedCollections,
    upToDate,
    note: upToDate
      ? "Snapshot matches current payload-types.ts. No drift detected."
      : "Drift detected. Review changes and run `npm run sync-schema` to refresh the snapshot (and update tool defaults/validation if needed).",
  };
}
